window.REC_META = {"repo": "AnalizadorRostroUNOQ-v3", "subtitle": "Seis piezas por segmento y cambio de cámara en caliente", "description": "La V3 del analizador agrega creatividades propias para cada combinación de género y banda de edad, y un campo IP Webcam en la interfaz que prueba, aplica y persiste la fuente sin reiniciar el servicio. El resto del pipeline sigue igual: YuNet, tracker IoU, UTKFace y stream MJPEG, todo local.", "repo_url": "https://github.com/wanderc137/AnalizadorRostroUNOQ-v3", "page_url": "https://wanderc137.github.io/AnalizadorRostroUNOQ-v3/", "poster_text": "La V3 del analizador agrega creatividades propias para cada combinación de género y banda de edad, y un campo IP Webcam en la interfaz que prueba, aplica y persiste la fuente sin reiniciar el servicio. El resto del pipeline sigue igual: YuNet, tracker IoU, UTKFace y stream MJPEG, todo local.", "commands": ["./scripts/start_server.sh", "curl -s http://127.0.0.1:8001/healthz", "curl -s http://127.0.0.1:8001/api/status | python3 -m json.tool", "curl -s \"http://127.0.0.1:8001/api/camera/probe?url=192.0.2.50:8080\"", "curl -s -X POST http://127.0.0.1:8001/api/camera/source -H 'Content-Type: application/json' -d '{\"source\":\"192.0.2.50:8080\"}'"], "chapters": [{"time": "0:06", "label": "EL PROBLEMA", "title": "La escena ya no depende de la cámara integrada"}, {"time": "0:23", "label": "ARQUITECTURA", "title": "FastAPI sirve la API y la interfaz desde el mismo proceso"}, {"time": "0:40", "label": "DETECCIÓN", "title": "YuNet se carga desde el ONNX y Haar queda de respaldo"}, {"time": "0:57", "label": "CLASIFICACIÓN", "title": "La edad sale de un softmax de ocho clases"}, {"time": "1:15", "label": "SEGMENTACIÓN", "title": "Del bucket a la creatividad: género más banda"}, {"time": "1:33", "label": "IP WEBCAM", "title": "Una IP suelta se convierte en la URL canónica"}, {"time": "1:51", "label": "PROBAR", "title": "Validar la cámara sin cortar el stream actual"}, {"time": "2:07", "label": "CAMBIO EN CALIENTE", "title": "Aplicar con rollback si la IP no responde"}, {"time": "2:26", "label": "PERSISTENCIA", "title": "Actualizar .env sin reescribir el resto"}, {"time": "2:43", "label": "STREAM", "title": "MJPEG con un solo productor de JPEG"}, {"time": "3:01", "label": "INTERFAZ", "title": "Estado, visor y una única acción manual"}, {"time": "3:17", "label": "CÓMO EJECUTARLO", "title": "Servicio, puerto y verificación"}], "width": 104, "height": 34, "duration": 225.89, "title": "Analizador de Rostros v3 · creatividades e IP Webcam"};
